def findMaximumNum(str, K):
    def max_at_index(s, k, index):
        if k == 0 or index == len(s):
            return s
        max_digit = s[index]
        for i in range(index + 1, len(s)):
            if s[i] > max_digit:
                max_digit = s[i]
        if max_digit != s[index]:
            k -= 1
        for i in range(len(s) - 1, index - 1, -1):
            if s[i] == max_digit:
                s = s[:index] + s[i] + s[index+1:i] + s[index] + s[i+1:]
                break
        return max_at_index(s, k, index + 1)

    return max_at_index(str, K, 0)

